from math import factorial

def bell_number(n):
    # Helper function to calculate binomial coefficients
    def binom(n, k):
        return factorial(n) // (factorial(k) * factorial(n - k))

    bell = [0] * (n + 1)
    bell[0] = 1

    for i in range(1, n + 1):
        bell[i] = 0
        for j in range(i):
            bell[i] += bell[j] * binom(i - 1, j)

    return bell[n]

# Count the number of ways to partition a set of size n
def partition_ways(n):
    total_partitions = sum(bell_number(i) for i in range(n + 1))
    return total_partitions

