def is_Monotonic(arr):
    def is_increasing(nums):
        return all(nums[i] <= nums[i + 1] for i in range(len(nums) - 1))

    def is_decreasing(nums):
        return all(nums[i] >= nums[i + 1] for i in range(len(nums) - 1))

    return is_increasing(arr) or is_decreasing(arr)

