def bubble_sort(arr):
    n = len(arr)
    swapped = True
    gap = n

    while gap != 1 or swapped == True:
        gap = max(1, int(gap / 1.3))
        swapped = False

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

def comb_sort(arr):
