def max_sum(arr):
    n = len(arr)

    # Initialize MIS and MDS arrays
    mis = [0] * n
    mds = [0] * n

    # Calculate MIS
    for i in range(n):
        mis[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                mis[i] = max(mis[i], mis[j] + arr[i])

    # Calculate MDS
    for i in reversed(range(n)):
        mds[i] = arr[i]
        for j in reversed(range(i + 1, n)):
            if arr[j] < arr[i]:
                mds[i] = max(mds[i], mds[j] + arr[i])

    # Calculate the maximum sum of bitonic subsequence
    max_sum_bitonic = 0
    for i in range(n):
        max_sum_bitonic = max(max_sum_bitonic, mis[i] + mds[i] - arr[i])

    return max_sum_bitonic

